if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_backup_timestamp() {
    local mount="${argc_d:-}"
    if [[ -n "$mount" ]]; then
        tmutil listbackups -d "$mount" 2>/dev/null
    else
        tmutil listbackups 2>/dev/null
    fi | gawk -F/ 'NF > 1 && $NF ~ /^[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]-[0-9]{6}$/ { print $NF }'
}

_choice_destination_id() {
    _helper_tmutil_destinations | gawk -F '\t' '$1 != "" { print $1 "\t" $2 }'
}

_choice_destination_mount() {
    _helper_tmutil_destinations | gawk -F '\t' '$3 != "" { print $3 "\t" $2 }'
}

_choice_mount_point() {
    mount 2>/dev/null | gawk 'NF >= 3 { print $3 }'
}

_choice_snapshot_date() {
    _argc_util_comp_path
    tmutil listlocalsnapshotdates 2>/dev/null | gawk '/^[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]-[0-9]{6}$/'
}

_helper_tmutil_destinations() {
    tmutil destinationinfo -X 2>/dev/null |
        plutil -convert json -o - - 2>/dev/null |
        jq -b -r '(.Destinations // [])[] | [(.ID // ""), (.Name // ""), (.MountPoint // "")] | @tsv'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
